/// <summary>
///  designed from AVA
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataSourceEventHandler(formDataSourceStr(ReturnTable, SalesLine), FormDataSourceEventType::Written)]
public static void SalesLine_OnWritten(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormDataSource  salesLine_ds = sender;
    SalesLine       salesLine = salesLine_ds.cursor();
    FormRun         formRun = sender.formRun();
    FormDataSource  specDiscSalesLine_DS = formRun.dataSource('AVASpecialDiscSalesLine');

    specDiscSalesLine_DS.refresh();
    AVASpecialDiscSalesLine specialDiscSalesLine = specDiscSalesLine_DS.cursor();

    if (specialDiscSalesLine.RecId == 0
        || (specialDiscSalesLine.RecId  && specialDiscSalesLine.InventTransId != salesLine.InventTransId))
    {
        specialDiscSalesLine.initFromSalesParameters();
        specialDiscSalesLine.initFromSpecDiscSalesTable(AVASpecialDiscSalesOrder::find(salesLine.SalesId));
        specDiscSalesLine_DS.write();
    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataSourceEventHandler(formDataSourceStr(SalesTable, AVASpecialDiscSalesLine), FormDataSourceEventType::Written)]
public static void AVASpecialDiscSalesLine_OnWritten(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormRun                 formRun = sender.formRun();
    FormDataSource          salesLine_DS = formRun.dataSource('SalesLine');
    salesLine_DS.reread();
    salesLine_DS.refresh();
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[FormDataSourceEventHandler(formDataSourceStr(ReturnTable, SalesLine), FormDataSourceEventType::Initialized)]
public static void SalesLine_OnInitialized(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormRun     formRun = sender.formRun();
    sender.object(fieldNum(SalesLine, AVAQuotationId)).registerOverrideMethod(methodStr(FormDataObject, lookup), methodStr(AVAReturnTableFrm_Extension, avaQuotationLookup), formRun);
}
